-- 2026-10-28 시즌 큐레이션: 추워진 날씨 겨울 상품 50개 (애드픽 MCP search_products 결과, affid 고정 goshopping 수익링크)
-- 사전 조건: 20261028130000_affiliate_seasonal_source.sql 적용, 동일 external_key seasonal 행 없음
begin;
do $$ begin
  if (select count(*) from public.affiliate_products where source_type = 'seasonal') <> 0 then
    raise exception 'seasonal rows already exist';
  end if;
end $$;
do $$ begin
  if (select count(*) from public.affiliate_products where source_type = 'seasonal' and is_active) <> 50 then
    raise exception 'unexpected seasonal row count';
  end if;
end $$;
commit;
